css:
.print-format {
  margin-top: 25mm;
  margin-bottom: 13mm;
  header-spacing: 3;
  margin-left: 11mm;
  margin-right: 11mm;
  padding: 0 !important;
  min-height: 0 !important;
  font-size: 8.5pt;
}
html body .print-format, body .print-format { margin: 0 !important; padding: 0 !important; min-height: 0 !important; }
html body, body[onload] { padding: 0 !important; margin: 0 !important; }

.print-format .afm,
.print-format .afm td,
.print-format .afm th,
.print-format .afm div,
.print-format .afm span {
  font-family: "Noto Sans Arabic", "Noto Sans", "DejaVu Sans", sans-serif !important;
}
.print-format .afm .en, .print-format .afm .num, .print-format .afm .ltr, .print-format .afm .num span {
  font-family: "Noto Sans", "DejaVu Sans", sans-serif !important;
}
.print-format .afm {
  color: #171717;
  font-size: 8.5pt;
  line-height: 14px;
  font-weight: normal;
  direction: rtl;
  text-align: right;
  -webkit-print-color-adjust: exact;
}
.afm * { box-sizing: border-box; }
.afm p { margin: 0; }
.afm b, .afm strong { font-weight: bold; }

.afm .ar { font-size: 7pt; line-height: 12px; font-weight: normal; color: #5f5f5f; }
.afm .en { font-size: 6pt; line-height: 10px; font-weight: normal; color: #5f5f5f; direction: ltr; unicode-bidi: embed; }
.afm .pair { display: table; width: 100%; line-height: 12px; }
.afm .pair .ar { display: table-cell; text-align: right; white-space: nowrap; vertical-align: baseline; }
.afm .pair .en { display: table-cell; text-align: left; white-space: nowrap; vertical-align: baseline; padding: 0 4px 0 0; }

.afm .num { white-space: nowrap; direction: ltr; unicode-bidi: embed; text-align: right; }
.afm .ctr { text-align: center !important; }
.afm .ltr { direction: ltr; unicode-bidi: embed; }

.afm table { width: 100%; border-collapse: collapse; table-layout: fixed; border-spacing: 0; }
.print-format .afm td, .print-format .afm th { padding: 1px 4px !important; vertical-align: top !important; word-wrap: break-word; }

.afm .head { margin: 0 0 8px 0; border-bottom: 1.2pt solid #00844e; }
.print-format .afm .head > tbody > tr > td { padding: 0 0 4px 0 !important; vertical-align: bottom !important; }
.afm .head .t-ar { font-size: 13pt; line-height: 20px; font-weight: bold; display: block; white-space: nowrap; }
.afm .head .t-en { font-size: 8.5pt; line-height: 14px; color: #5f5f5f; direction: ltr; unicode-bidi: embed; display: block; white-space: nowrap; }

.afm .kv { margin: 0 0 8px 0; }
.print-format .afm .kv td { border: 0.75pt solid #d0d0d0; }
.print-format .afm .head .kv { margin: 0; }
.print-format .afm .kv td.empty { border: 0; }
.afm .kv .v { display: block; font-size: 8.5pt; line-height: 14px; color: #171717; white-space: nowrap; }
.afm .kv .v.wrap { white-space: normal; }
.afm .kv .v.num { text-align: right; }
.afm .kv .v.b { font-weight: bold; }
.afm .kv td.plabel { border: 0; border-top: 1.2pt solid #00844e; vertical-align: middle !important; }
.afm .kv td.plabel .ar { font-weight: bold; color: #00844e; }

.afm .items { margin: 0 0 8px 0; }
.afm .items thead { display: table-header-group; }
.afm .items tfoot { display: table-footer-group; }
.afm .items tr { page-break-inside: avoid; }
.print-format .afm .items th {
  background: #f4f4f4;
  border-top: 1.2pt solid #00844e;
  border-bottom: 0.75pt solid #d0d0d0;
  text-align: right !important;
  font-weight: bold;
  white-space: nowrap;
  vertical-align: bottom !important;
}
.afm .items th .ar { font-weight: bold; color: #171717; display: block; white-space: nowrap; }
.afm .items th .en { display: block; white-space: nowrap; }
.print-format .afm .items td { border-bottom: 0.75pt solid #d0d0d0; font-size: 8.5pt; line-height: 14px; vertical-align: middle !important; }
.print-format .afm .items td.num { text-align: right !important; }
.afm .items .sub { color: #5f5f5f; font-size: 7pt; line-height: 12px; }

.afm .band { page-break-inside: avoid; margin: 0 0 8px 0; }
.print-format .afm .band > tbody > tr > td { padding: 0 !important; }
.afm .qr img { width: 96px; height: 96px; display: block; }
.print-format .afm .band td.words { padding: 0 8px !important; }
.afm .words .w { font-size: 8.5pt; line-height: 14px; margin: 0 0 8px 0; }
.print-format .afm .sign td { border-bottom: 0.75pt solid #5f5f5f; padding: 0 !important; height: 40px; }
.print-format .afm .sign td.gap { border: 0; }
.print-format .afm .tot td { border-bottom: 0.75pt solid #d0d0d0; vertical-align: middle !important; }
.afm .tot td.num { font-weight: bold; }
.afm .tot tr.grand td { background: #00844e; color: #ffffff; border-bottom: 0; font-weight: bold; }
.afm .tot tr.grand .ar, .afm .tot tr.grand .en { color: #ffffff; }
.afm .tot tr.grand .ar { font-weight: bold; }

.afm .note { font-size: 7pt; line-height: 12px; color: #171717; page-break-inside: avoid; overflow: hidden; }
.print-format .afm .note p, .print-format .afm .note .ql-editor { margin: 0 !important; padding: 0 !important; line-height: 12px !important; font-size: 7pt !important; }
.afm .note img { float: left; max-height: 80px; width: auto; margin: 0 0 0 8px; }
.afm .note .k { display: inline-block; padding: 0 0 0 4px; white-space: nowrap; }
.afm .note .k, .afm .note .k .en { color: #5f5f5f; font-size: 7pt; line-height: 12px; }

.afm-hdr .logo img { height: 48px; width: auto; display: block; }
.afm-hdr .n-ar { font-size: 13pt; line-height: 20px; font-weight: bold; display: block; color: #171717; white-space: nowrap; }
.afm-hdr .n-en { font-size: 8.5pt; line-height: 14px; color: #00844e; direction: ltr; unicode-bidi: embed; display: block; white-space: nowrap; }
.print-format .afm-hdr td { padding: 0 !important; vertical-align: middle !important; }
.afm-hdr .ids td { font-size: 8.5pt; line-height: 14px; white-space: nowrap; vertical-align: baseline !important; }
.afm-hdr .ids td.num { text-align: right !important; }
.afm-hdr .ids .k { font-size: 7pt; color: #5f5f5f; }
.afm-hdr .ids .k.ltr { font-size: 6pt; }
.afm-hdr .rule td { height: 8px; }
.afm-hdr .rule .thin { border-bottom: 0.75pt solid #00844e; }
.afm-hdr .rule .thick { border-bottom: 2.4pt solid #00844e; }

.print-format .afm-ftr td { border-top: 0.75pt solid #00844e; padding: 4px 0 0 0 !important; font-size: 7pt; line-height: 12px; color: #5f5f5f; vertical-align: top !important; }
.afm-ftr .ltr { white-space: nowrap; }
.afm-ftr .co { white-space: nowrap; }
.afm-ftr .ltr2 { direction: ltr; text-align: right; white-space: nowrap; padding: 0 4px 0 0; font-family: "Noto Sans", "DejaVu Sans", sans-serif; }
.afm-ftr .pg { white-space: nowrap; color: #171717; }

.print-format .afm-hdr td.nm { padding: 0 8px 0 0 !important; }
.print-format .afm.eos-n { font-size: 11pt; line-height: 22px; }
.afm.eos-n .ar { font-size: 8.5pt; line-height: 14px; }
.afm.eos-n .en { font-size: 7pt; line-height: 12px; }
.afm.eos-n .pair { line-height: 14px; }

.afm.eos-n .head { margin: 0 0 16px 0; border-bottom: 0; }
.afm.eos-n .head .t-ar { font-size: 16pt; line-height: 24px; }
.print-format .afm.eos-n .head > tbody > tr > td { padding: 0 !important; }
.afm.eos-n .head .t-en { font-size: 11pt; line-height: 22px; }
.afm.eos-n .sec { margin: 0 0 16px 0; }
.afm.eos-n .kv { margin: 0; }
.print-format .afm.eos-n .kv td { padding: 4px 8px !important; }
.afm.eos-n .kv .v { font-size: 11pt; line-height: 22px; }
.afm.eos-n .kv .v.mix { direction: ltr; unicode-bidi: embed; text-align: right; }
.print-format .afm.eos-n .kv td.plabel { padding: 4px 0 4px 0 !important; }
.afm.eos-n .kv td.plabel .ar { font-size: 11pt; line-height: 22px; }

.print-format .afm.eos-n .tot td { padding: 4px 8px !important; }
.afm.eos-n .tot td.num { font-size: 11pt; line-height: 22px; }
.afm.eos-n .tot tr.grand .ar { font-size: 11pt; line-height: 22px; }

.afm.eos-n .bitext { margin: 0 0 8px 0; }
.print-format .afm.eos-n .bitext td { padding: 0 !important; vertical-align: top !important; }
.print-format .afm.eos-n .bitext td.ar-col { padding: 0 0 8px 0 !important; border-bottom: 0.75pt solid #d0d0d0; text-align: right; }
.print-format .afm.eos-n .bitext td.en-col { padding: 8px 0 0 0 !important; direction: ltr; text-align: left; }
.afm.eos-n .bitext p { margin: 0; font-size: 11pt; line-height: 22px; color: #171717; }
.afm.eos-n .bitext p + p { margin: 8px 0 0 0; }

.afm.eos-n .sign { margin: 16px 0 0 0; }
.print-format .afm.eos-n .sign td { height: 64px; }
.afm.eos-n .p2 { page-break-before: always; }

html:
{%- macro money(v) -%}{{ frappe.utils.fmt_money((v or 0) | abs, 2) }}{%- endmacro -%}
{%- macro qty(v) -%}{%- set q = (v or 0) | abs -%}{{ frappe.utils.fmt_money(q, 0) if q == (q | int) else frappe.utils.fmt_money(q, 2) }}{%- endmacro -%}
{%- macro pct(v) -%}{{ '%g' | format(frappe.utils.flt(v or 0, 2)) }}%{%- endmacro -%}{%- macro lbl(key, en=none, stack=false) -%}
{%- set ar = _(key, lang='ar') -%}{%- set e = en or key -%}
{%- if stack -%}{% if ar != key %}<span class="ar">{{ ar }}</span>{% endif %}<span class="en">{{ e }}</span>
{%- else -%}<span class="pair">{% if ar != key %}<span class="ar">{{ ar }}</span>{% else %}<span class="ar ltr">{{ e }}</span>{% endif %}{% if ar != key %}<span class="en">{{ e }}</span>{% endif %}</span>
{%- endif -%}
{%- endmacro -%}{%- macro kvgrid(items, cols) -%}
{%- set ns = namespace(f=[], row=[], w=0, rows=[]) -%}
{%- for it in items -%}{%- if it[2] -%}{%- set ns.f = ns.f + [it] -%}{%- endif -%}{%- endfor -%}
{%- for it in ns.f -%}
  {%- set sp = it[3] if it | length > 3 else 1 -%}
  {%- if ns.w + sp > cols -%}{%- set ns.rows = ns.rows + [ns.row] -%}{%- set ns.row = [] -%}{%- set ns.w = 0 -%}{%- endif -%}
  {%- set ns.row = ns.row + [it] -%}{%- set ns.w = ns.w + sp -%}
{%- endfor -%}
{%- if ns.row -%}{%- set ns.rows = ns.rows + [ns.row] -%}{%- endif -%}
{%- if ns.rows -%}
<table class="kv">
  <colgroup>{% for i in range(cols) %}<col style="width:{{ (100 / cols) | round(3) }}%">{% endfor %}</colgroup>
  {%- for r in ns.rows %}
  <tr>
    {%- set rn = namespace(w=0) -%}
    {%- for it in r -%}{%- set sp = it[3] if it | length > 3 else 1 -%}{%- set rn.w = rn.w + sp %}
    <td{% if sp > 1 %} colspan="{{ sp }}"{% endif %}>{{ lbl(it[0], it[1]) }}<span class="v {{ it[4] if it | length > 4 else '' }}">{{ it[2] }}</span></td>
    {%- endfor -%}
    {%- if rn.w < cols %}<td class="empty" colspan="{{ cols - rn.w }}"></td>{% endif %}
  </tr>
  {%- endfor %}
</table>
{%- endif -%}
{%- endmacro -%}{%- macro title_block(t_key, t_en, meta, cols=4, tw=24) -%}
{%- set t_ar = _(t_key, lang='ar') -%}
<table class="head">
  <colgroup><col style="width:{{ tw }}%"><col style="width:{{ 100 - tw }}%"></colgroup>
  <tr>
    <td><span class="t-ar">{{ t_ar if t_ar != t_key else t_en }}</span>{% if t_ar != t_key %}<span class="t-en">{{ t_en }}</span>{% endif %}</td>
    <td>{{ kvgrid(meta, cols) }}</td>
  </tr>
</table>
{%- endmacro -%}{%- macro parties_block(parties, cols=12) -%}
{%- for p in parties -%}
{%- if p[0] -%}
<table class="kv" style="margin:0"><colgroup><col></colgroup><tr><td class="plabel">{{ lbl(p[0], p[1]) }}</td></tr></table>
{%- endif -%}
{{ kvgrid(p[2], cols) }}
{%- endfor -%}
{%- endmacro -%}{%- macro items_table(rows, columns) -%}
{%- set ns = namespace(c=[]) -%}
{%- for c in columns -%}{%- if c.get('show', true) -%}{%- set ns.c = ns.c + [c] -%}{%- endif -%}{%- endfor -%}
<table class="items">
  <colgroup>{% for c in ns.c %}<col{% if c.w %} style="width:{{ c.w }}%"{% endif %}>{% endfor %}</colgroup>
  <thead>
    <tr>{% for c in ns.c %}<th{% if c.t == 'money' %} class="n"{% endif %}>{{ lbl(c.l, c.en, stack=true) }}</th>{% endfor %}</tr>
  </thead>
  <tbody>
  {%- for r in rows %}
    <tr>
    {%- for c in ns.c -%}
      {%- set v = r.get(c.k) -%}
      {%- if c.t == 'idx' %}<td class="num ctr">{{ v }}</td>
      {%- elif c.t == 'qty' %}<td class="num ctr">{{ qty(v) }}</td>
      {%- elif c.t == 'money' %}<td class="num">{{ money(v) }}</td>
      {%- elif c.t == 'pct' %}<td class="num ctr">{% if v %}{{ pct(v) }}{% endif %}</td>
      {%- elif c.t == 'text' %}<td>{{ v or '' }}{% if r.get(c.k ~ '_sub') %} <span class="sub">{{ r.get(c.k ~ '_sub') }}</span>{% endif %}</td>
      {%- else %}<td class="ctr">{{ v or '' }}</td>
      {%- endif -%}
    {%- endfor %}
    </tr>
  {%- endfor %}
  </tbody>
</table>
{%- endmacro -%}{%- macro totals_block(lines, grand) -%}
<table class="tot">
  <colgroup><col style="width:66%"><col style="width:34%"></colgroup>
  {%- for l in lines %}{% if l | length < 4 or l[3] %}
  <tr><td>{{ lbl(l[0], l[1]) }}</td><td class="num">{{ money(l[2]) }}</td></tr>
  {%- endif %}{% endfor %}
  <tr class="grand"><td>{{ lbl(grand[0], grand[1]) }}</td><td class="num">{{ money(grand[2]) }}</td></tr>
</table>
{%- endmacro -%}{%- macro zatca_block(doc, details=none) -%}
{%- set z = namespace(d=details, src=none) -%}
{%- if z.d is none and doc.doctype == 'Sales Invoice' and frappe.db.exists('Sales Invoice Additional Fields', {'sales_invoice': doc.name}) -%}
  {%- set z.d = get_phase_2_print_format_details(doc) -%}
{%- endif -%}
{%- set z.src = ((z.d.siaf.qr_image_src if z.d and z.d.siaf else none) or doc.get('ksa_einv_qr')) -%}
{%- if z.src %}<img src="{{ z.src }}" alt="ZATCA QR">{% endif -%}
{%- endmacro -%}{%- macro signature_block(signers) -%}
<table class="sign">
  <colgroup>{% for s in signers %}{% if not loop.first %}<col style="width:5%">{% endif %}<col>{% endfor %}</colgroup>
  <tr>{% for s in signers %}{% if not loop.first %}<td class="gap"></td>{% endif %}<td>{{ lbl(s[0], s[1]) }}</td>{% endfor %}</tr>
</table>
{%- endmacro -%}{%- macro band_block(qr_html, middle_html, totals_html, qr_w=28, totals_w=48) -%}
<table class="band">
  <colgroup>{% if qr_html | trim %}<col style="width:{{ qr_w }}mm">{% endif %}<col><col style="width:{{ totals_w }}%"></colgroup>
  <tr>
    {%- if qr_html | trim %}<td class="qr">{{ qr_html }}</td>{% endif %}
    <td class="words">{{ middle_html }}</td>
    <td>{{ totals_html }}</td>
  </tr>
</table>
{%- endmacro -%}{%- macro notes_block(remarks, terms) -%}
{%- set rm = (remarks or '') | trim -%}
{%- set tx = (terms or '') | replace('<p><br></p>', '') -%}
{%- if (rm and rm != 'No Remarks') or (tx | striptags | trim) or ('<img' in tx) %}
<div class="note">
  {%- if rm and rm != 'No Remarks' %}<div><span class="k">{{ _('Remarks', lang='ar') }} <span class="en">Remarks</span>:</span> {{ rm }}</div>{% endif %}
  {%- if tx | striptags | trim or '<img' in tx %}{{ tx }}{% endif %}
</div>
{%- endif -%}
{%- endmacro -%}{%- macro bitext(keys, cols=2) -%}
{%- set ns = namespace(ar=[], any=false) -%}
{%- for k in keys -%}{%- set a = _(k, lang='ar') -%}{%- if a != k -%}{%- set ns.any = true -%}{%- set ns.ar = ns.ar + [a] -%}{%- endif -%}{%- endfor -%}
<table class="bitext">
  {%- if ns.any and cols == 2 %}
  <colgroup><col style="width:50%"><col style="width:50%"></colgroup>
  <tr><td class="ar-col">{% for a in ns.ar %}<p>{{ a }}</p>{% endfor %}</td><td class="en-col ltr">{% for k in keys %}<p>{{ k }}</p>{% endfor %}</td></tr>
  {%- else %}
  {%- if ns.any %}<tr><td class="ar-col">{% for a in ns.ar %}<p>{{ a }}</p>{% endfor %}</td></tr>{% endif %}
  <tr><td class="en-col ltr">{% for k in keys %}<p>{{ k }}</p>{% endfor %}</td></tr>
  {%- endif %}
</table>
{%- endmacro -%}
{%- set _afm_company = doc.get('company') or (frappe.db.get_value('Employee', doc.get('employee'), 'company') if doc.get('employee') else none) or frappe.defaults.get_global_default('company') -%}{%- set _afm_co = frappe.db.get_value('Company', _afm_company, ['company_name', 'company_name_in_arabic', 'tax_id', 'company_logo'], as_dict=1) or {} -%}
{%- set _afm_zbs = frappe.db.get_value('ZATCA Business Settings', {'company': _afm_company}, 'name') if _afm_company else none -%}
{%- set _afm_ns = namespace(cr='', street='', postal='') -%}
{%- if _afm_zbs -%}
  {%- set _afm_z = frappe.get_doc('ZATCA Business Settings', _afm_zbs) -%}
  {%- for r in _afm_z.other_ids -%}{%- if r.type_code == 'CRN' and r.value and not _afm_ns.cr -%}{%- set _afm_ns.cr = r.value -%}{%- endif -%}{%- endfor -%}
  {%- set _afm_ns.street = _afm_z.street or '' -%}{%- set _afm_ns.postal = _afm_z.postal_code or '' -%}
{%- endif -%}{%- set afm = {
