{%- set mm = frappe.utils.cint(frappe.utils.flt(doc.months)) -%}
{%- set dd = frappe.utils.cint(frappe.utils.flt(doc.days)) -%}
{%- set dur = (yy ~ 'Y | ' ~ mm ~ 'M | ' ~ dd ~ 'D') if (doc.years or doc.months or doc.days) else '' -%}
