{%- set rsn_ar = _(doc.end_of_service_reason, lang='ar') if doc.end_of_service_reason else '' -%}

<div class="afm eos-n" dir="rtl" lang="ar">

{{ title_block('Clearing End of Service', 'End of Service Settlement', [
